        exercises = listOf(
            Exercise.ReadingChoice(id = "tcf_reading_2026_viewpoints_e1", prompt = "Quel point commun ressort des deux contributions ?", passage = "Deux contributions originales fictives au bulletin d’un quartier, à propos de la fermeture temporaire de la rue de l’école aux voitures :\n\nDocument A — Lina :\n« Pendant les horaires d’entrée et de sortie des classes, une rue sans voitures rendrait l’arrivée à l’école plus agréable. Je propose un essai de six semaines, avec un accès maintenu pour les secours et les personnes dont la mobilité l’exige. Les livraisons ordinaires pourraient être effectuées à d’autres heures. Avant de décider de poursuivre, il faudrait observer les déplacements dans la rue et dans les voies voisines. »\n\nDocument B — Marc :\n« Je partage l’objectif de rendre les trajets scolaires plus sûrs. Cependant, si les parents se garent tous dans la rue parallèle, nous aurons déplacé le problème. Je ne m’oppose pas à un essai, mais il faut prévoir des points de dépose à distance et informer les familles avant son lancement. Le bilan devrait aussi recueillir l’avis des riverains des rues voisines, pas seulement celui des personnes devant l’école. »", options = listOf("Les deux auteurs demandent une fermeture permanente dès le lendemain.", "Les deux auteurs refusent de consulter les riverains.", "Les deux auteurs acceptent l’idée d’un essai plutôt qu’une décision immédiate et définitive.", "Les deux auteurs veulent supprimer tout accès, y compris celui des secours."), correctOptionIndex = 2, explanation = "Lina propose un essai de six semaines ; Marc précise qu’il ne s’oppose pas à un essai, tout en demandant des mesures d’accompagnement. Les deux positions permettent une expérimentation. Ni une fermeture permanente immédiate ni l’exclusion des secours ne constitue leur position commune.", hint = "Compare leur position sur la manière de décider, plutôt que d’opposer automatiquement proposition et réserve."),
